// Metadata is explicit on every descendant so routing/filtering does not need
// to infer a system from a translated title or from the reused base solution.
function withSystem(node, systemId) {
  return { ...node, systemId, imageKey: node.imageKey || imageFor(systemId),
    ...(node.children ? { children: node.children.map(child => withSystem(child, systemId)) } : {}) };
}
